INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43311, 'Leviticus 13:23', 'Leviticus', 13, 23, 'خو که چېرې هغه بدل شوی او خپور شوی نه وي، دا یوازې د دانې داغ دی او کاهن به هغه کس پاک اعلان کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_23.mp3', '', 1761754199, 1761754199),
(43312, 'Leviticus 13:24', 'Leviticus', 13, 24, 'کله چې د یو چا پوستکی سوځېدلی وي او د سوځېدلي ځای په خامه غوښه کې یو سوربخن سپین یا سپین داغ راښکاره شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_24.mp3', '', 1761754199, 1761754199),
(43313, 'Leviticus 13:25', 'Leviticus', 13, 25, 'نو کاهن دې هغه داغ معاینه کړي. که چېرې په هغه کې ویښتان سپین شوي وو او د پوستکي څخه ژور ښکاره کېده، دا د پوستکي یوه ساري ناروغي ده چې په هغه سوځېدلي ځای کې پیل شوې ده. کاهن به هغه کس ناپاک اعلان کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_25.mp3', '', 1761754199, 1761754199),
(43314, 'Leviticus 13:26', 'Leviticus', 13, 26, 'خو که چېرې کاهن هغه معاینه کړي او په داغ کې سپین ویښتان نه وي او هغه د پوستکي څخه ژور نه وي او مړاوی شوی وي، بیا دې کاهن هغه کس د اوو ورځو دپاره بېل وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_26.mp3', '', 1761754199, 1761754199),
(43315, 'Leviticus 13:27', 'Leviticus', 13, 27, 'په اوومه ورځ دې کاهن هغه معاینه کړي. که چېرې هغه خپریږي، کاهن به هغه کس ناپاک اعلان کړي، دا د پوستکي یوه ساري ناروغي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_27.mp3', '', 1761754199, 1761754199),
(43316, 'Leviticus 13:28', 'Leviticus', 13, 28, 'خو که چېرې بیاهم زخم بدل شوی نه وي او خپور شوی نه وي، خو مړاوی شوی وي، نو دا د سوځېدلي ځای پړسوب دی او کاهن به هغه کس پاک اعلان کړي. دا یوازې د سوځېدلي ځای داغ دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_28.mp3', '', 1761754199, 1761754199),
(43317, 'Leviticus 13:29', 'Leviticus', 13, 29, 'که چېرې د یو سړي یا د یوې ښځې په سر یا په زنه باندې زخم وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_29.mp3', '', 1761754199, 1761754199),
(43318, 'Leviticus 13:30', 'Leviticus', 13, 30, 'نو کاهن دې هغه زخم معاینه کړي. که چېرې هغه د پوستکي څخه ژور ښکاري او زیړ نري ویښتان په کې وي، نو کاهن به هغه کس ناپاک اعلان کړي. دا یو خارښت دی او د سر یا د زنې ساري ناروغي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_30.mp3', '', 1761754199, 1761754199),
(43319, 'Leviticus 13:31', 'Leviticus', 13, 31, 'خو کله چې کاهن د ناسور دا ډول زخم معاینه کړي، که چېرې هغه د پوستکي څخه ژور نه ښکاره کېده، خو بیاهم تور ویښتان په کې نه وو، نو کاهن دې هغه ناروغه کس اووه ورځې بېل وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_31.mp3', '', 1761754199, 1761754199),
(43320, 'Leviticus 13:32', 'Leviticus', 13, 32, 'په اوومه ورځ دې کاهن هغه زخم معاینه کړي. که چېرې خارښت خپور شوی نه ؤ او زیړ ویښتان په کې نه وو او د پوستکي څخه ژور نه ښکاره کېده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_32.mp3', '', 1761754199, 1761754199),
(43321, 'Leviticus 13:33', 'Leviticus', 13, 33, 'نو د هغه کس ټول سر باید وخرایل شي پرته له زخمي ځای څخه. کاهن دې هغه نورې اووه ورځې بېل وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_33.mp3', '', 1761754199, 1761754199),
(43322, 'Leviticus 13:34', 'Leviticus', 13, 34, 'په اوومه ورځ دې کاهن هغه خارښت بیا معاینه کړي، که چېرې هغه په پوستکي کې خپور شوی نه ؤ او د پوستکي څخه ژور نه ښکاره کېده، کاهن به هغه پاک اعلان کړي. هغه کس باید خپل کالي ووینځي او پاک به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_34.mp3', '', 1761754199, 1761754199),
(43323, 'Leviticus 13:35', 'Leviticus', 13, 35, 'خو که چېرې د هغه د پاکوالي د اعلان څخه وروسته خارښت خپور شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_35.mp3', '', 1761754199, 1761754199),
(43324, 'Leviticus 13:36', 'Leviticus', 13, 36, 'کاهن دې هغه معاینه کړي او که چېرې خارښت په پوستکي کې خپور شوی وي، کاهن دا اړتیا نه لري چې زیړ ویښتان ولټوي، هغه کس ناپاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_36.mp3', '', 1761754199, 1761754199),
(43325, 'Leviticus 13:37', 'Leviticus', 13, 37, 'خو که چېرې د هغه په نظر کې هغه بدل شوی نه وي او تور ویښتان په کې راشنه شوي وي، دا خارښت روغ شوی دی. هغه کس پاک دی او کاهن به هغه همداسې پاک اعلان کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_37.mp3', '', 1761754199, 1761754199),
(43326, 'Leviticus 13:38', 'Leviticus', 13, 38, 'کله چې د یو سړي یا د یوې ښځې په پوستکي باندې سپین داغونه وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_38.mp3', '', 1761754199, 1761754199),
(43327, 'Leviticus 13:39', 'Leviticus', 13, 39, 'نو کاهن دې هغه کس معاینه کړي. که چېرې دا داغونه مړاوي او سپین وي، هغه یوه بې زیانه ګرمکه ده چې په بدن باندې راختلې ده، هغه کس پاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_39.mp3', '', 1761754199, 1761754199),
(43328, 'Leviticus 13:40', 'Leviticus', 13, 40, 'که چېرې یو سړي خپل ویښتان له لاسه ورکړي وي او ګنجی شوی وي، هغه پاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_40.mp3', '', 1761754199, 1761754199),
(43329, 'Leviticus 13:41', 'Leviticus', 13, 41, 'که چېرې هغه د خپلې کوپړۍ یا تندي ویښتان له لاسه ورکړي وي او لوڅ تندی ولري، هغه پاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_41.mp3', '', 1761754199, 1761754199),
(43330, 'Leviticus 13:42', 'Leviticus', 13, 42, 'خو که چېرې د هغه په ګنجي سر یا لوڅ تندي باندې سوربخن سپین زخم وي، دا د پوستکي یوه ساري ناروغي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_42.mp3', '', 1761754199, 1761754199),
(43331, 'Leviticus 13:43', 'Leviticus', 13, 43, 'کاهن دې هغه معاینه کړي او که چېرې زخم سوربخن سپین وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_43.mp3', '', 1761754199, 1761754199),
(43332, 'Leviticus 13:44', 'Leviticus', 13, 44, 'نو هغه سړی ناروغ او ناپاک دی. کاهن به هغه ناپاک اعلان کړي، ځکه چې د هغه په سر باندې زخم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_44.mp3', '', 1761754199, 1761754199),
(43333, 'Leviticus 13:45', 'Leviticus', 13, 45, 'هغه کس چې په داسې ساري ناروغۍ اخته وي باید شلېدلي کالي واغوندي، خپل ویښتان دې ببر پرېږدي، خپله خوله دې پټه کړي او داسې چیغې دې ووهي: زه ناپاک یم! زه ناپاک یم!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_45.mp3', '', 1761754199, 1761754199),
(43334, 'Leviticus 13:46', 'Leviticus', 13, 46, 'ترڅو پورې چې هغه کس په دې ناروغۍ باندې اخته وي هغه ناپاک پاتې کیږي. هغه باید یوازې او د کمپ څخه دباندې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_46.mp3', '', 1761754199, 1761754199),
(43335, 'Leviticus 13:47', 'Leviticus', 13, 47, 'که چېرې کوم کالي چڼاسکې وهلي وي، که هغه د وړیو څخه جوړ شوي وي یا د کتان کالي وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_47.mp3', '', 1761754199, 1761754199),
(43336, 'Leviticus 13:48', 'Leviticus', 13, 48, 'د کتان یا وړیو ټوکر، یا څرمن او یا داسې شی وي چې د څرمنې څخه جوړ شوی وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_48.mp3', '', 1761754199, 1761754199),
(43337, 'Leviticus 13:49', 'Leviticus', 13, 49, 'که چېرې هغه چڼاسکه شنه بخنه یا سره بخنه وي، نو دا یوه خپرېدونکې چڼاسکه ده او کاهن ته باید وروښودل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_49.mp3', '', 1761754199, 1761754199),
(43338, 'Leviticus 13:50', 'Leviticus', 13, 50, 'کاهن دې هغه چڼاسکه معاینه کړي او هغه شی دې اووه ورځې بېل کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_50.mp3', '', 1761754199, 1761754199),
(43339, 'Leviticus 13:51', 'Leviticus', 13, 51, 'په اوومه ورځ دې هغه بیا معاینه کړي. که چېرې چڼاسکه خپره شوې وه، نو هغه شی ناپاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_51.mp3', '', 1761754199, 1761754199),
(43340, 'Leviticus 13:52', 'Leviticus', 13, 52, 'کاهن باید هغه کالي وسوځوي، ځکه چې چڼاسکه خرابوونکې ده او هغه دې وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_52.mp3', '', 1761754199, 1761754199),
(43341, 'Leviticus 13:53', 'Leviticus', 13, 53, 'خو کله چې کاهن هغه معاینه کړي او دا معلومه کړي چې چڼاسکه په هغه شي باندې نه ده خپره شوې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_53.mp3', '', 1761754199, 1761754199),
(43342, 'Leviticus 13:54', 'Leviticus', 13, 54, 'هغه به دا حکم وکړي چې دا خراب شوی شی ووینځل شي. بیا دې هغه د نورو اوو ورځو دپاره بېل کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_54.mp3', '', 1761754199, 1761754199),
(43343, 'Leviticus 13:55', 'Leviticus', 13, 55, 'وروسته له دې چې خراب شوی شی ووینځل شي، کاهن دې هغه بیا معاینه کړي. که چېرې چڼاسکې خپل رنګ نه وي بدل کړی، که څه هم هغه خپره شوې نه ده، بیاهم هغه ناپاک دی. که دا خرابوالی په مخکې وي یا شاته، تاسو باید دا شی وسوځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_55.mp3', '', 1761754199, 1761754199),
(43344, 'Leviticus 13:56', 'Leviticus', 13, 56, 'خو کله چې کاهن هغه معاینه کړي، که چېرې د هغه شي د وینځلو څخه وروسته چڼاسکه مړاوې شوې وي، هغه دې خرابه شوې برخه وشلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_56.mp3', '', 1761754199, 1761754199),
(43345, 'Leviticus 13:57', 'Leviticus', 13, 57, 'خو که چېرې چڼاسکه په پورتنیو شیانو باندې بیا راښکاره شي، نو دا خپرېدونکې ده او په هرڅه باندې چې چڼاسکه وي، نو خاوند یې باید هغه شی وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_57.mp3', '', 1761754199, 1761754199),
(43346, 'Leviticus 13:58', 'Leviticus', 13, 58, 'که چېرې هغه کس هغه شی ووینځي او چڼاسکه ورکه شي هغه دې بیا ووینځل شي، نو هغه شی به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_58.mp3', '', 1761754199, 1761754199),
(43347, 'Leviticus 13:59', 'Leviticus', 13, 59, 'دا قوانین د هغو کالیو په هکله دي چې چڼاسکې وهلي وي، که هغه د وړیو یا کتان څخه جوړ شوي وي، د وړیو یا کتان ټوکر وي یا هغه شیان وي چې د څرمنې څخه جوړ شوي وي. نو په دې ډول به کاهن کولای شي دا پرېکړه وکړي چې ایا دا شیان پاک دي یا ناپاک.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_59.mp3', '', 1761754199, 1761754199),
(43348, 'Numbers 27:1', 'Numbers', 27, 1, 'محله، نوعه، حجله، ملکه او ترصه د صلفحاد لورګانې وې. صلفحاد د حافر زوی ؤ، حافر د جلعاد زوی ؤ، جلعاد د ماخیر زوی ؤ، ماخیر د منسي زوی ؤ او منسي د یوسف زوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_1.mp3', '', 1761754199, 1761754199),
(43349, 'Numbers 27:2', 'Numbers', 27, 2, 'یوه ورځ د هغه لورګانې د سپېڅلې خېمې دروازې ته لاړلې او هلته یې د موسی، العازار کاهن، د اسراییلو نورو مشرانو او د اسراییلو د ټول قوم سره لیدنه کتنه وکړه. هغوی وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_2.mp3', '', 1761754199, 1761754199),
(43350, 'Numbers 27:3', 'Numbers', 27, 3, '«زمونږ پلار په دښته کې مړ شو او د هغه څخه هېڅ زامن پاتې نه شول. هغه د قورح د پیروانو څخه چې د څښتن په وړاندې یې سرکښي کړې وه، نه ؤ بلکې هغه د خپلې ګناه له امله مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_3.mp3', '', 1761754199, 1761754199),
(43351, 'Numbers 27:4', 'Numbers', 27, 4, 'یوازې په دې خاطر چې هغه هېڅ زامن نه درلودل، ولې زمونږ د پلار نوم د خپلې طایفې څخه ورک شي؟ مونږ ته د خپل پلار د خپلوانو په منځ کې ځمکه راکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_4.mp3', '', 1761754199, 1761754199),
(43352, 'Numbers 27:5', 'Numbers', 27, 5, 'موسی د هغوی دعوه څښتن ته وړاندې کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_5.mp3', '', 1761754199, 1761754199),
(43353, 'Numbers 27:6', 'Numbers', 27, 6, 'او څښتن هغه ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_6.mp3', '', 1761754199, 1761754199),
(43354, 'Numbers 27:7', 'Numbers', 27, 7, '«د صلفحاد لورګانې چې څه غواړي هغه سم دي. هغوی ته د خپل پلار د خپلوانو په منځ کې ځمکه ورکړه. پرېږده چې د هغه میراث د دوی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_7.mp3', '', 1761754199, 1761754199),
(43355, 'Numbers 27:8', 'Numbers', 27, 8, 'اسراییلیانو ته ووایه: ‹کله چې یو سړی بې زویه مړ شي، د هغه لور ته به د هغه ځمکه په میراث پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_8.mp3', '', 1761754199, 1761754199),
(43356, 'Numbers 27:9', 'Numbers', 27, 9, 'که چېرې هغه هېڅ لور ونه لري، د هغه ورونو ته به ځمکه په میراث پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_9.mp3', '', 1761754199, 1761754199),
(43357, 'Numbers 27:10', 'Numbers', 27, 10, 'خو که چېرې هغه هېڅ ورونه ونه لري، د هغه ترونو ته به ځمکه په میراث پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_10.mp3', '', 1761754199, 1761754199),
(43358, 'Numbers 27:11', 'Numbers', 27, 11, 'که چېرې هغه ترونه ونه لري، په هغه طایفه کې باید د هغه تر ټولو نژدې خپلوان ته د هغه ځمکه ورکړل شي. د اسراییلو قوم باید دا د یو قانوني شرط په توګه رعایت کړي، لکه څنګه چې ما څښتن تاته حکم وکړ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_11.mp3', '', 1761754199, 1761754199),
(43359, 'Numbers 27:12', 'Numbers', 27, 12, 'څښتن موسی ته وویل: «د عباریم غرونو ته وخېژه او هغه ځمکه وګوره چې زه یې اسراییلیانو ته ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_12.mp3', '', 1761754199, 1761754199),
(43360, 'Numbers 27:13', 'Numbers', 27, 13, 'کله چې ته هغه ووینې، نو د خپل ورور هارون په شان به مړ شې او د خپلو نیکونو سره به یوځای شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_13.mp3', '', 1761754199, 1761754199),
(43361, 'Numbers 27:14', 'Numbers', 27, 14, 'ځکه چې تاسو دواړو د صین په دښته کې زما د امر څخه سرکښي وکړه. هغه وخت چې ټول قوم په مریبه کې زما په ضد شکایت وکړ، تاسو د هغوی په مخکې زما د پاک قدرت درناوی ونه کړ.» (مریبه په قادش کې د صین په دښته کې یوه چینه ده.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_14.mp3', '', 1761754199, 1761754199),
(43362, 'Numbers 27:15', 'Numbers', 27, 15, 'موسی دعا وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_15.mp3', '', 1761754199, 1761754199),
(43363, 'Numbers 27:16', 'Numbers', 27, 16, '«ای څښتن خدایه، ای د ژوندون سرچینې، زه دعا کوم چې داسې یو کس وټاکه چې د قوم مشري وکولای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_16.mp3', '', 1761754199, 1761754199),
(43364, 'Numbers 27:17', 'Numbers', 27, 17, 'ستا قوم یو داسې کس ته اړتیا لري چې په جګړه کې ورته لارښوونه وکړي. که نه، نو هغوی به د داسې پسونو په شان شي چې بې شپونه یو خوا او بل خوا سرګردانه ګرځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_17.mp3', '', 1761754199, 1761754199),
(43365, 'Numbers 27:18', 'Numbers', 27, 18, 'څښتن موسی ته وویل: «د نون زوی یوشع لایق سړی دی، خپل لاس د هغه په سر باندې کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_18.mp3', '', 1761754199, 1761754199),
(43366, 'Numbers 27:19', 'Numbers', 27, 19, 'بیا یې د العازار کاهن او اسراییلیانو په مخکې ودروه او یوشع د هغوی د نوي مشر په توګه وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_19.mp3', '', 1761754199, 1761754199),
(43367, 'Numbers 27:20', 'Numbers', 27, 20, 'د خپلو اختیاراتو څخه دې لږ څه هغه ته ورکړه، ترڅو د اسراییلو ټول قوم د هغه اطاعت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_20.mp3', '', 1761754199, 1761754199),
(43368, 'Numbers 27:21', 'Numbers', 27, 21, 'کله چې د څښتن څخه د لارښوونې د اخیستلو دپاره اړتیا پېښه شي، نو یوشع باید العازار ته ورشي. العازار به د اوریم او تمیم څخه په کار اخیستلو سره د هغه رضا معلومه کړي. په دې ډول به یوشع او د اسراییلو ټول قوم ته معلومه شي چې څه باید وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers27_verse_21.mp3', '', 1761754199, 1761754199),
