(43400, 'Joshua 23:13', 'Joshua', 23, 13, 'نو بیا باور ولرئ چې څښتن خدای به نور دا قومونه ستاسو له مخې څخه لېرې نه کړي، بلکې هغوی به ستاسو دپاره د دام یا د لومې په شان خطرناک شي او ستاسو د شاګانو دپاره به د قمچینې په شان شي او ستاسو په سترګو کې به د اغزیو په شان شي. او دا به تر هغه وخته پورې دوام ومومي، ترڅو ستاسو څخه هېڅوک په دې ښې ځمکه کې چې خپل څښتن خدای درته درکړې ده پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua23_verse_13.mp3', '', 1761754199, 1761754199),
(43401, 'Joshua 23:14', 'Joshua', 23, 14, 'اوس زما د مړینې وخت رارسېدلی دی. تاسو هر یو په خپل زړه کې پوهېږئ چې ستاسو څښتن خدای تاسو ته هغه ټول ښه شیان درکړي دي چې وعده یې کړې وه. هره وعده چې هغه کړې ده، هغه پوره شوې ده او یوه وعده یې هم ماته شوې نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua23_verse_14.mp3', '', 1761754199, 1761754199),
(43402, 'Joshua 23:15', 'Joshua', 23, 15, 'خو لکه څنګه چې زمونږ څښتن خدای ستاسو سره د ټولو ښو شیانو وعده کړې ده او هغه یې سرته رسولې ده، نو هماغسې هغه به په تاسو باندې ټولې بدۍ هم راولي، ترڅو تاسو د دې ښې ځمکې څخه چې هغه تاسو ته درکړې ده، ورک کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua23_verse_15.mp3', '', 1761754199, 1761754199),
(43403, 'Joshua 23:16', 'Joshua', 23, 16, 'که چېرې تاسو هغه لوظ مات کړئ چې د هغه حکم یې په تاسو باندې کړی دی او د نورو خدایانو خدمت او عبادت وکړئ، نو بیا به هغه په قهر شي او تاسو ته به سزا درکړي او تاسو به زر د هغې ځمکې څخه ورک شئ چې زمونږ څښتن خدای تاسو ته درکړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua23_verse_16.mp3', '', 1761754199, 1761754199),
(43404, 'Psalms 77:1', 'Psalms', 77, 1, 'په لوړ اواز خدای ته فریاد کومه په لوړ اواز ورته فریاد کومه چې ماته غوږ ونیسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_1.mp3', '', 1761754199, 1761754199),
(43405, 'Psalms 77:2', 'Psalms', 77, 2, 'زه د سختۍ په وخت کې کړمه څښتن ته رجوع زه په دعا کې ټوله شپه پورته کوم لاسونه خو زما زړه تسلي نه شي موندلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_2.mp3', '', 1761754199, 1761754199),
(43406, 'Psalms 77:3', 'Psalms', 77, 3, 'کله چې زه رایادوم خدای نو زه زګېروي کومه کله چې ډوب شمه خیالونو کې زه زړه تورن کېږمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_3.mp3', '', 1761754199, 1761754199),
(43407, 'Psalms 77:4', 'Psalms', 77, 4, 'پټېدو ته دې پرېنښودلې سترګې زما دومره نا‌ارام یم چې کولای زه خبرې نه شم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_4.mp3', '', 1761754199, 1761754199),
(43408, 'Psalms 77:5', 'Psalms', 77, 5, 'کومه فکر په خپل تېرو ورځو رایادومه پخواني کلونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_5.mp3', '', 1761754199, 1761754199),
